mapper.select:
SELECT l.pictureId AS pictureId, COUNT(*) AS downloadCount FROM picture_download_log l JOIN picture p ON p.id = l.pictureId WHERE l.createTime >= #{startTime} AND l.createTime < #{endTime} AND p.isDelete = 0 AND p.spaceId IS NULL AND p.reviewStatus = 1
AND p.category = #{category}
GROUP BY l.pictureId ORDER BY downloadCount DESC, l.pictureId DESC
